"""V8 presenter draft; writes isolated story, shot contract and review text."""
from pathlib import Path
import json
import re

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'work/audio-v8'
OUT.mkdir(parents=True,exist_ok=True)
old=json.loads((ROOT/'src/story.json').read_text(encoding='utf8'))

# id, chapter, display text, visible action, source IDs
rows=[
('o01','overview','你在家按下开关，灯亮了。几十公里外，一台海上风机正在转。但真正让人好奇的是：这么高的机器，脚下全是水，它怎么站得稳，还把电送到家？','0–12秒：主风机近景到完整塔架，电能亮点指向岸上；生活设问不出现人物身份。',['G01']),
('o02','overview','先看海面下面。钢管撑成的架子叫导管架，风和浪推来的力，要经过它传到桩，再交给周围的土。海床托不住，上面的机器再好也白搭。','12–22秒：沿塔筒入水，导管架到桩、土体逐级亮起；载荷箭头固定构件坐标。',['Z06']),
('o03','overview','水再深一点，可以让风机浮起来。几根浮筒撑开，就像把椅子腿分开；浮力托住重量，底部压载降低重心，系泊缆牵住位置。','22–34秒：出水后围绕半潜式平台；浮筒/压载剖面和系泊缆各只强调一处。',['G01','Z01']),
('o04','overview','浪来了，浮体会摇，塔顶也跟着动，叶片迎风的角度随之改变。控制器一调叶片，整台机器受到的力又变了。各管各的，算不清这笔账。','34–45秒：同一浮体轻微六自由度示意；波浪→平台→叶片→控制的作用顺序可追踪。',['Z01','Z05']),
('o05','overview','王立忠带领的浙江大学海上风电团队，开发了仿真软件Zwind。它把风、浪、土体、结构和控制放进同一套计算，追踪这种连锁反应。下面就沿着一台直驱风机，看看能量怎么一路送上岸。','45–63秒：返主机巡航；一处成果标题随世界位置出现，风/浪/土体/控制以模型对应部位点亮，不能冒称此画面是Zwind求解输出。',['Z01','Z05']),
('h01','hook','这趟旅程有两件事一直同行：一条路传递力量，把风机稳住；另一条路传递能量，把灯点亮。先看叶片，风究竟从哪里使上劲？','主机到叶片，载荷线向下、电能线沿轴向分开，随后只保留叶片焦点。',['G01']),
('w01','wind','叶片看着像一块长板，剖开却像飞机的机翼。空气从两侧流过，压力分布发生变化，合起来给叶片一个力。其中沿着圆周的那一部分，就能推着风轮转。','真实叶片翼型剖面；双侧流线和压力分布，合力分解到切向分量；不画同到达时间的错误流线。',['G01']),
('w02','wind','推门时，手离门轴越远越省力。叶片也是同一个道理：力乘上到轴心的距离，决定它多会带动旋转，这就叫转矩。叶尖走得快，叶根走得慢，所以叶片沿长度还要扭一扭。','先轴心—半径—切向力，再转矩圆弧；镜头沿叶片根到尖，显出扭转，不切去孤立纸风车。',['G01']),
('w03','wind','风一阵大一阵小，叶片也会弯。到底弯了多少？浙江大学陈鹰、钱鹏团队研制了叶片实时形变监测设备。公开报道里，他们把设备带到零下三十六摄氏度的漠河，检查严寒下能不能可靠工作。','同一叶片的小幅弹性变形和参考轮廓；标注测量点，以官方实验照片/页面小范围世界展示补充，气温是报道试验环境。',['Z02']),
('w04','wind','知道叶片的状态，才好及时调节，也好安排维护。眼前这些细小的气动力，最终汇成轮毂上的转动。风给出的这笔能量，就这样交到了主轴手里。','测量点返回整片→轮毂→主轴，监测研究只是案例，不宣称本场景使用该设备。',['G01','Z02']),
('r01','rotor','打开机舱，先认清两个角色：主轴负责传递旋转，轴承负责支撑，让它转得顺，还要承受风轮传来的载荷。这台采用直驱结构，主轴直接带发电机，走的是一条很短的传动路线。','外壳渐透明后轴、主轴承依次受光；爆炸图保持同轴，直驱无增速齿轮箱。',['G01']),
('r02','rotor','叶片转一圈，发电机的转子也转一圈。它转得慢，却拧得很有劲，所以这里用一个大直径发电机来接住。磁铁和线圈沿圆周排开，真正的能量转换就发生在它们之间。','转子和轮毂同角速度；定子静止，极数与结构为原理示意，不伪造设计规格。',['G01']),
('g01','generator','把磁铁从线圈旁边移过去，线圈两端就会出现电压。发电机把这件小事做成连续动作：转子带着磁场一圈圈经过，线圈感受到的磁通不断变化，电压便持续产生。','转子磁极经过定子铜线圈；只显示近侧局部磁通，线圈保持固定；相位与机械运动一致。',['G01']),
('g02','generator','接上电路，电流就有了通路，电能向外送；与此同时，发电机会反过来牵制转子。像骑自行车时带上发电小灯，灯越亮，脚下越费劲。电能来自风轮持续做功。','电流路径从线圈到端子；反向电磁转矩和正向气动转矩形成一对；自行车仅口语比喻，不切尺度。',['G01']),
('g03','generator','所以，发得多，也要接得稳。控制器一边看转速，一边调整发电机的电磁转矩；风太强时，还会让叶片转一个角度，少取一点力，保护这整套机器。','同一轴系保持动态，转矩调节后叶片缓慢变桨；两个变化先后呈现不同时闪烁。',['G01','Z03']),
('c01','converter','问题又来了：风速会变，发电机输出的交流节奏也会变，电网却有自己的节拍。变流器先把电整理到直流环节，再重新合成为跟得上电网的交流。','从发电机端子沿电缆到变流器；变量交流→直流母线→同步交流三段，波形靠设备呈现。',['G01']),
('c02','converter','可以想成两个人合奏：速度要合上，起拍的位置也要合上，这就是频率和相位。变流器协调电流、电压和输出功率，电网的节拍才能保持稳定。','输入/输出波形由失配到同频同相；不用暗示变流器可独自稳定整个电网。',['G01']),
('c03','converter','这也是海上风电控制研究要解决的问题。浙江大学司玉林的公开研究方向，就包括海上风电优化控制和海洋装备智能运维：让机器能判断眼前的状态，再做出合适的动作。','控制器传感→判断→执行的三步回路；成果标题写研究方向，不能写具体算法已部署。',['Z03']),
('t01','transformer','电准备送远了，还要过升压这一关。同样的输送功率，把电压提高，电流就可以减小。电缆像一条长路，电流经过电阻会发热，路越长，这笔损耗越值得算清楚。','电流沿塔内电缆落到变压器；低压大电流/高压小电流对照绑定同一路径。',['G01']),
('t02','transformer','比如在电阻相同、输送功率相同的简化条件下，电压翻倍，电流大约减半，电阻发热就降到四分之一。省下来的，是原本要在路上变成热的那部分能量。','同一段导体，电压2倍→电流1/2→I²R损耗1/4三步；明确简化条件，不能把变压器效率算成1/4。',['G01']),
('t03','transformer','一台台风机把电汇集起来，经过海上升压站，再走向海底电缆。海面上看着只有几座塔，水面下，电网的连接已经铺展开了。','海上变电站与风场集电连线，再向海缆转移，不错误暗示每台机舱设备都相同。',['G01']),
('k01','cable','海缆里面有导体、绝缘和保护层。它要挡住海水，也要承受敷设和海底环境带来的变形。一个位置弯得过厉害，或被海流冲成悬空段，都可能让长期服役变得危险。','海缆同位置剖切，导体→绝缘→铠装/护套；海床局部冲刷形成悬跨示意。',['Z04']),
('k02','cable','浙大海洋学院葛晗等老师指导的学生团队，就把传感器测到的信息，用来重构管缆变形、评估风险。这个监测方案在二零二四年的研究生能源装备创新设计大赛中获得了一等奖。','沿海缆出现测量点与连续位移曲线；只称竞赛研究方案，原位监测能力源于官方报道。',['Z04']),
('s01','shore','电终于上岸，接入电网，再经过变电和配电，走到灯、插座和实验室的仪器。你打开开关时，用到的是整个电力系统共同送来的能量，海上风电是其中的一份。','沿海缆上岸到变电/配电，再到多个负荷；多电源汇入，避免指定某个电子来自风机。',['G01']),
('s02','shore','风还会变化。多座风场、其他电源、储能和调度要一起配合，发电和用电才能不断接上。海上的设备要耐风浪，岸上的系统也要接得住它的起伏。','风功率缓慢起伏，电网节点和储能响应，建筑负荷连续运行；不表达储能能无限平滑。',['G01']),
('s03','shore','从叶片形变监测，到整机耦合计算，再到海缆健康监测，浙大的这些研究，分别守着这条链上的不同环节。后面这个系列，就沿着这条路，把这些问题一个个讲清楚。','不再集中目录卡；沿已有三处研究锚点亮起短线，回到完整风场，只一句系列承诺。',['Z02','Z05','Z04']),
('e01','ending','一阵风，先变成旋转，再变成电，最后走进日常生活。让这条路走得稳，是海洋工程师每天要解的题。下一集，就从叶片开始：一块薄薄的翼型，究竟怎样把风变成转动？','结束巡航回风场；下一集标题绑定叶片附近的世界坐标，保留足够读字时间。',['G01']),
]

story={k:v for k,v in old.items() if k not in ['sentences','captions','narrativeNotes','narrativeRevision','pronunciationNotes']}
story.update({'title':'海上的风，怎样点亮岸上的灯？','version':'V8','targetDuration':367,'sentences':[],
              'captions':[],'narrativeRevision':'2026-10-14-v8-presenter-official-research',
              'narrativeNotes':{'angle':'中立介绍者：风机基础与浙大公开研究穿插','institutionalBoundary':'不自称学生/团队成员；公开成果归属按原文，教学模型不称官方原型或求解结果','status':'draft-awaiting-measured-TTS'},
              'pronunciationNotes':{'系泊':'xì bó；口播写细泊','轮毂':'lún gǔ；口播写轮谷','转矩':'zhuǎn jǔ；口播写转举','载荷':'zài hè；按完整句检测','Zwind':'Zee wind；首次画面保留 Zwind'}})
for id,ch,text,visual,sources in rows:
    spoken=text.replace('系泊','细泊').replace('轮毂','轮谷').replace('转矩','转举').replace('Zwind','Zee wind')
    story['sentences'].append({'id':id,'chapter':ch,'text':text,'spoken':spoken,'visual':visual,'sourceIds':sources,'audio':f'public/audio/v8/{id}.wav'})
story['audio']={**story['audio'],'narration':'public/audio/v8/narration.wav','status':'pending-v8-synthesis','subjectiveListeningChecked':False}
story['sources']=[{k:v for k,v in x.items() if k!='text'} for x in json.loads((ROOT/'research/iterations/v8-audio/sources-fetched.json').read_text(encoding='utf8')) if x.get('status')==200]
(OUT/'story-v8-draft.json').write_text(json.dumps(story,ensure_ascii=False,indent=2),encoding='utf8')
headlines=[
 {'id':'zwind','cueIds':['o05'],'chapter':'overview','headline':'Zwind · 整机耦合分析','detail':'浙大海上风电团队','sourceIds':['Z01','Z05'],'boundary':'公开软件研究能力；此教学模型未标记为其计算结果'},
 {'id':'blade-monitor','cueIds':['w03'],'chapter':'wind','headline':'叶片弯了多少？','detail':'陈鹰、钱鹏团队 · 实时形变监测','sourceIds':['Z02'],'boundary':'报道2025-12漠河极寒测试；不声称后续量产已完成'},
 {'id':'control','cueIds':['c03'],'chapter':'converter','headline':'状态 → 判断 → 动作','detail':'司玉林 · 海上风电优化控制','sourceIds':['Z03'],'boundary':'公开研究方向，不代表特定已部署算法'},
 {'id':'cable-monitor','cueIds':['k02'],'chapter':'cable','headline':'海缆也需要“体检”','detail':'葛晗等指导 · 管缆监测方案','sourceIds':['Z04'],'boundary':'2024研究生竞赛一等奖方案，不宣称规模商业部署'},
]
(OUT/'research-headlines-v8.json').write_text(json.dumps(headlines,ensure_ascii=False,indent=2),encoding='utf8')
lines=['# V8 介绍者口播与逐句画面对照','', '时间暂以原章节为规划锚点；以完整句源真实时长重建，禁止整轨加速或截字。','']
for scene in old['scenes']:
    ch=scene['chapter'];lines += [f"## {ch} · 规划 {scene['start']:.2f}–{scene['end']:.2f} 秒",'']
    for cue in story['sentences']:
        if cue['chapter']==ch: lines += [f"**{cue['id']}** {cue['text']}",f"画面：{cue['visual']}",f"依据：{', '.join(cue['sourceIds'])}",'']
(OUT/'V8-旁白与逐句画面对照.md').write_text('\n'.join(lines),encoding='utf8')
print(json.dumps({'cues':len(rows),'characters':sum(len(re.sub(r'[^\u4e00-\u9fffA-Za-z0-9]','',r[2])) for r in rows),'draft':str(OUT/'story-v8-draft.json')},ensure_ascii=False))
